const APPS_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbzQGO_Ll-Hc40udLnxqwU1GJoQ3NjksIvuoek6se-GAkAIqWJhP-5FShwus5eGZLgAb/exec';

