// ============================================================
// PENGATURAN PENUTUPAN APLIKASI
// Tanggal & jam otomatis tutup: 2 Juni 2026 pukul 21:00 WIB (UTC+7)
// ============================================================
const APP_CLOSE_CONFIG = {
  // Waktu tutup otomatis: 2 Juni 2026 21:00 WIB = UTC 14:00
  AUTO_CLOSE_TIME: new Date('2026-06-02T14:00:00Z'),
  // Key localStorage untuk menyimpan status manual
  STORAGE_KEY: 'smpn6_app_closed',
  STORAGE_MANUAL_KEY: 'smpn6_app_manual_closed'
};

/**
 * Cache status akses dari server.
 * Catatan penting:
 * - localStorage hanya berlaku di browser yang sama.
 * - Status global tutup/buka harus disimpan di Google Apps Script.
 */
let appStatusCache = null;

function _isTrue(v) {
  return v === true || v === 'true' || v === 1 || v === '1';
}

function _fallbackAppStatus() {
  const autoClosed = new Date() >= APP_CLOSE_CONFIG.AUTO_CLOSE_TIME;
  const manualClosed = localStorage.getItem(APP_CLOSE_CONFIG.STORAGE_MANUAL_KEY) === 'true';
  return {
    closed: manualClosed || autoClosed,
    manualClosed,
    manualOpen: false,
    autoClosed,
    source: 'local-fallback'
  };
}

/**
 * Ambil status akses siswa dari Google Apps Script.
 * Endpoint yang dibutuhkan di Code.gs: action=getAppStatus.
 */
async function getAppClosedStatus() {
  const autoClosedLocal = new Date() >= APP_CLOSE_CONFIG.AUTO_CLOSE_TIME;

  if (isDemoMode()) {
    appStatusCache = _fallbackAppStatus();
    return appStatusCache;
  }

  try {
    const res = await fetch(`${APPS_SCRIPT_URL}?action=getAppStatus&t=${Date.now()}`, {
      method: 'GET',
      cache: 'no-store'
    });
    if (!res.ok) throw new Error('HTTP ' + res.status);

    const json = await res.json();
    const manualClosed = _isTrue(json.manualClosed);
    const manualOpen   = _isTrue(json.manualOpen);
    const autoClosed   = _isTrue(json.autoClosed) || autoClosedLocal;

    // Jika server lama hanya mengirim "closed", tetap kompatibel.
    const serverClosed = _isTrue(json.closed);
    const closed = manualClosed ? true : manualOpen ? false : (serverClosed || autoClosed);

    appStatusCache = {
      closed,
      manualClosed,
      manualOpen,
      autoClosed,
      message: json.message || '',
      source: 'server'
    };
    return appStatusCache;
  } catch (err) {
    console.warn('[getAppClosedStatus] Gagal cek status server, pakai fallback lokal:', err);
    appStatusCache = _fallbackAppStatus();
    return appStatusCache;
  }
}

/**
 * Simpan status akses siswa ke Google Apps Script.
 * closed=true  => tutup untuk semua perangkat/browser.
 * closed=false => buka untuk semua perangkat/browser, termasuk override setelah jam otomatis.
 */
async function setAppClosedStatus(closed) {
  if (isDemoMode()) {
    if (closed) localStorage.setItem(APP_CLOSE_CONFIG.STORAGE_MANUAL_KEY, 'true');
    else localStorage.removeItem(APP_CLOSE_CONFIG.STORAGE_MANUAL_KEY);
    appStatusCache = _fallbackAppStatus();
    return appStatusCache;
  }

  // Pakai GET agar tidak terkena CORS preflight Google Apps Script.
  // POST dengan header application/json sering menyebabkan error: Failed to fetch.
  const url = `${APPS_SCRIPT_URL}?action=setAppStatus&closed=${closed ? 'true' : 'false'}&t=${Date.now()}`;
  const res = await fetch(url, {
    method: 'GET',
    cache: 'no-store'
  });
  if (!res.ok) throw new Error('HTTP ' + res.status);

  const json = await res.json();

  // Cache lokal hanya sebagai fallback jika server gagal diakses.
  if (closed) localStorage.setItem(APP_CLOSE_CONFIG.STORAGE_MANUAL_KEY, 'true');
  else localStorage.removeItem(APP_CLOSE_CONFIG.STORAGE_MANUAL_KEY);

  appStatusCache = {
    closed: _isTrue(json.closed),
    manualClosed: _isTrue(json.manualClosed) || closed === true,
    manualOpen: _isTrue(json.manualOpen) || closed === false,
    autoClosed: _isTrue(json.autoClosed) || (new Date() >= APP_CLOSE_CONFIG.AUTO_CLOSE_TIME),
    message: json.message || '',
    source: 'server'
  };
  return appStatusCache;
}

/**
 * Fungsi sinkron tetap dipertahankan untuk kompatibilitas UI lama.
 * Untuk keputusan login siswa, gunakan getAppClosedStatus() yang cek server.
 */
function isAppClosed() {
  if (appStatusCache) return appStatusCache.closed;
  return _fallbackAppStatus().closed;
}

/** Tutup aplikasi secara manual (fallback lokal; admin UI memakai setAppClosedStatus) */
function adminCloseApp() {
  localStorage.setItem(APP_CLOSE_CONFIG.STORAGE_MANUAL_KEY, 'true');
}

/** Reset/buka kembali aplikasi (fallback lokal; admin UI memakai setAppClosedStatus) */
function adminOpenApp() {
  localStorage.removeItem(APP_CLOSE_CONFIG.STORAGE_MANUAL_KEY);
}

/** Format waktu tutup otomatis untuk tampilan */
function formatAutoCloseTime() {
  // 2 Juni 2026, 21:00 WIB
  return '2 Juni 2026, 21:00 WIB';
}

