// ============================================================
// Ambil jsPDF dengan aman (berbagai cara ekspos library)
// ============================================================
function getJsPDF() {
  // jsPDF UMD v2.x → window.jspdf.jsPDF  (paling umum)
  if (window.jspdf && window.jspdf.jsPDF) return window.jspdf.jsPDF;
  // Kadang ter-assign langsung ke window.jsPDF
  if (window.jsPDF) return window.jsPDF;
  // Fallback: modul UMD mungkin ada di window.jspdf langsung sebagai constructor
  if (typeof window.jspdf === 'function') return window.jspdf;
  // Coba akses lewat properti lain (beberapa versi CDN berbeda)
  if (window.jspdf && typeof window.jspdf === 'object') {
    const keys = Object.keys(window.jspdf);
    for (const k of keys) {
      if (typeof window.jspdf[k] === 'function') return window.jspdf[k];
    }
  }
  return null;
}

// Tunggu jsPDF siap (maksimal 5 detik)
function waitForJsPDF(timeout = 5000) {
  return new Promise((resolve, reject) => {
    if (getJsPDF()) { resolve(getJsPDF()); return; }
    const interval = 100;
    let elapsed = 0;
    const timer = setInterval(() => {
      const pdf = getJsPDF();
      if (pdf) { clearInterval(timer); resolve(pdf); return; }
      elapsed += interval;
      if (elapsed >= timeout) {
        clearInterval(timer);
        reject(new Error('jsPDF tidak berhasil dimuat. Periksa koneksi internet dan refresh halaman.'));
      }
    }, interval);
  });
}

// ============================================================
// Utilitas halaman
// ============================================================
function showPage(pageId) {
  document.querySelectorAll('.page').forEach(p => {
    p.classList.remove('active');
    p.style.display = 'none';
  });
  const target = document.getElementById(pageId);
  if (target) {
    target.style.display = 'flex';
    target.classList.add('active');
    target.querySelectorAll('.animate-in').forEach(el => {
      el.style.animation = 'none';
      void el.offsetWidth;
      el.style.animation = '';
    });
  }
}

function showAlert(elId, msg, type = 'error') {
  const el = document.getElementById(elId);
  if (!el) return;
  el.className = 'alert-custom ' + type;
  el.innerHTML = `<i class="fas fa-${type==='error'?'exclamation-circle':type==='success'?'check-circle':'info-circle'}"></i> ${msg}`;
  el.classList.remove('d-none');
}
function hideAlert(elId) {
  const el = document.getElementById(elId);
  if (el) el.classList.add('d-none');
}

function togglePass(inputId, btn) {
  const inp = document.getElementById(inputId);
  if (inp.type === 'password') {
    inp.type = 'text';
    btn.innerHTML = '<i class="fas fa-eye-slash"></i>';
  } else {
    inp.type = 'password';
    btn.innerHTML = '<i class="fas fa-eye"></i>';
  }
}

function setLoading(prefix, isLoading) {
  const btnText = document.getElementById(prefix + '-btn-text');
  const spinner  = document.getElementById(prefix + '-spinner');
  if (!btnText || !spinner) return;
  if (isLoading) { btnText.classList.add('d-none'); spinner.classList.remove('d-none'); }
  else           { btnText.classList.remove('d-none'); spinner.classList.add('d-none'); }
}

// ============================================================
// Partikel
// ============================================================
function initParticles() {
  const container = document.getElementById('particles');
  if (!container) return;
  for (let i = 0; i < 18; i++) {
    const p = document.createElement('div');
    p.className = 'particle';
    const size = Math.random() * 50 + 10;
    p.style.cssText = `
      width:${size}px;height:${size}px;
      left:${Math.random()*100}%;top:${Math.random()*100}%;
      opacity:${Math.random()*.25+.05};
      animation-delay:${Math.random()*6}s;
      animation-duration:${Math.random()*4+4}s;
    `;
    container.appendChild(p);
  }
}

// ============================================================
// LOGIN SISWA
// ============================================================
async function loginSiswa() {
  const nisn = document.getElementById('siswa-nisn').value.trim();
  hideAlert('alert-siswa');

  // ── Cek status akses ke server agar berlaku di semua browser/HP ──
  const appStatus = await getAppClosedStatus();
  if (appStatus.closed) {
    const msg = appStatus.manualClosed
      ? '<i class="fas fa-lock"></i> Pengumuman kelulusan peserta didik akan terbuka secara otomatis tepat pada pukul 18.00 WIB.'
      : `<i class="fas fa-clock"></i> Masa pengumuman kelulusan telah <strong>berakhir</strong> pada ${formatAutoCloseTime()}. Terima kasih atas partisipasi Anda.`;
    showAlert('alert-siswa', msg, 'error');
    return;
  }

  if (!nisn) { showAlert('alert-siswa', 'NISN tidak boleh kosong.'); return; }

  setLoading('siswa', true);
  try {
    let found = null;

    if (isDemoMode()) {
      found = DEMO_DATA.find(d => String(d.NISN).trim() === nisn) || null;
    } else {
      if (allSiswa.length > 0) {
        found = allSiswa.find(d => String(d.NISN).trim() === nisn) || null;
      } else {
        const res  = await fetch(`${APPS_SCRIPT_URL}?action=getByNISN&nisn=${encodeURIComponent(nisn)}`);
        if (!res.ok) throw new Error('HTTP ' + res.status);
        const json = await res.json();
        if (json.status !== 'not_found') found = json.data || json || null;
      }
    }

    if (!found) {
      showAlert('alert-siswa', 'NISN <strong>' + nisn + '</strong> tidak ditemukan. Hubungi wali kelas Anda.');
      return;
    }
    currentSiswa = found;
    renderHasilSiswa(found);
    showPage('page-hasil-siswa');
  } catch (e) {
    console.error(e);
    showAlert('alert-siswa', 'Gagal terhubung ke server. Periksa koneksi internet Anda.');
  } finally {
    setLoading('siswa', false);
  }
}

function renderHasilSiswa(d) {
  const lulus = isStatusLulus(d.Status);

  document.getElementById('hasil-status-badge').innerHTML = lulus
    ? `<div class="status-badge-lulus"><i class="fas fa-graduation-cap"></i> LULUS</div>`
    : `<div class="status-badge-tidak"><i class="fas fa-times-circle"></i> TIDAK LULUS</div>`;

  const rows = [
    { k:'Nama',             v: d.Nama || '-' },
    { k:'NIS',              v: d.NIS  || '-' },
    { k:'NISN',             v: d.NISN || '-' },
    { k:'Tempat Lahir',     v: d.Tempat_Lahir || '-' },
    { k:'Tanggal Lahir',    v: formatTanggal(d.Tanggal_Lahir) || '-' },
    { k:'Status Kelulusan', v: `<span class="${lulus?'badge-lulus':'badge-tidak'}">${d.Status||'-'}</span>` },
  ];
  document.getElementById('hasil-data').innerHTML = rows.map(r =>
    `<div class="hasil-row"><span class="hasil-key">${r.k}</span><span class="hasil-val">${r.v}</span></div>`
  ).join('');

  const pernyataan = document.getElementById('hasil-pernyataan');
  if (lulus) {
    pernyataan.className = 'hasil-pernyataan pernyataan-lulus';
    pernyataan.innerHTML = `<i class="fas fa-check-circle"></i> Sesuai dengan keputusan Dewan Guru, <strong>${d.Nama}</strong> dinyatakan <strong>LULUS</strong> dari SMP Negeri 6 Batang Tahun Ajaran 2025/2026.`;
  } else {
    pernyataan.className = 'hasil-pernyataan pernyataan-tidak';
    pernyataan.innerHTML = `<i class="fas fa-info-circle"></i> Sesuai dengan keputusan Dewan Guru, <strong>${d.Nama}</strong> dinyatakan <strong>TIDAK LULUS</strong> dari SMP Negeri 6 Batang Tahun Ajaran 2025/2026. Silakan hubungi pihak sekolah.`;
  }

  // Pasang event listener tombol download siswa (aman, tidak inline)
  const btnDl = document.getElementById('btn-download-skl');
  if (btnDl) {
    btnDl.onclick = () => downloadSKL(d);
  }
}

