async function loginAdmin() {
  const user = document.getElementById('admin-user').value.trim();
  const pass  = document.getElementById('admin-pass').value.trim();
  hideAlert('alert-admin');
  if (!user || !pass) { showAlert('alert-admin', 'Username dan password wajib diisi.'); return; }
  if (user !== ADMIN_CREDENTIAL.user || pass !== ADMIN_CREDENTIAL.pass) {
    showAlert('alert-admin', 'Username atau password salah.'); return;
  }
  setLoading('admin', true);
  showPage('page-dashboard');
  setLoading('admin', false);
  // Inisialisasi panel pengaturan
  const settingsBody = document.getElementById('settings-body');
  if (settingsBody) settingsBody.style.display = 'none';
  refreshSettingsUI();
  await loadAllData();
}

// ============================================================
// PENGATURAN AKSES – UI ADMIN
// ============================================================
function toggleSettings() {
  const body    = document.getElementById('settings-body');
  const chevron = document.getElementById('settings-chevron');
  if (!body) return;
  const isOpen = body.style.display === 'block';
  body.style.display   = isOpen ? 'none' : 'block';
  chevron.style.transform = isOpen ? '' : 'rotate(180deg)';
  if (!isOpen) refreshSettingsUI();
}

async function refreshSettingsUI() {
  const status = await getAppClosedStatus();
  const isClosed   = status.closed;
  const isManual   = status.manualClosed;
  const isAutoTime = status.autoClosed;

  // Badge status otomatis
  const autoEl = document.getElementById('settings-auto-status');
  if (autoEl) {
    if (isAutoTime) {
      autoEl.className = 'settings-status-badge badge-closed';
      autoEl.innerHTML = '<i class="fas fa-lock"></i> Sudah Lewat';
    } else {
      autoEl.className = 'settings-status-badge badge-open';
      autoEl.innerHTML = '<i class="fas fa-clock"></i> Belum Tutup';
    }
  }

  // Deskripsi status saat ini
  const descEl = document.getElementById('settings-current-desc');
  if (descEl) {
    if (isClosed) {
      if (isManual) {
        descEl.innerHTML = '<span style="color:var(--tidak);"><i class="fas fa-lock"></i> <strong>DITUTUP MANUAL</strong> oleh admin. Siswa tidak bisa login.</span>';
      } else {
        descEl.innerHTML = '<span style="color:var(--tidak);"><i class="fas fa-clock"></i> <strong>TUTUP OTOMATIS</strong> karena sudah melewati batas waktu.</span>';
      }
    } else {
      descEl.innerHTML = '<span style="color:var(--lulus);"><i class="fas fa-lock-open"></i> <strong>TERBUKA</strong> – Siswa dapat login dan mengecek kelulusan.</span>';
    }
  }

  // Tombol
  const btnClose = document.getElementById('btn-close-app');
  const btnOpen  = document.getElementById('btn-open-app');
  // Tombol: jika sedang terbuka tampilkan tombol Tutup; jika sedang tertutup tampilkan tombol Buka.
  // Ini juga memungkinkan admin membuka akses setelah jadwal tutup otomatis terlewati.
  if (btnClose) btnClose.style.display = !isClosed ? 'inline-flex' : 'none';
  if (btnOpen)  btnOpen.style.display  = isClosed ? 'inline-flex' : 'none';
}

async function adminCloseAppUI() {
  if (!confirm('Apakah Anda yakin ingin MENUTUP akses login siswa sekarang?\nSiswa tidak akan bisa mengecek kelulusan sampai dibuka kembali.')) return;

  try {
    await setAppClosedStatus(true);
    await refreshSettingsUI();
    showAlert('alert-settings', '<i class="fas fa-check-circle"></i> Akses login siswa berhasil <strong>ditutup untuk semua perangkat/browser</strong>.', 'success');
  } catch (err) {
    console.error(err);
    showAlert('alert-settings', 'Gagal menutup akses di server: ' + err.message, 'error');
  }
}

async function adminOpenAppUI() {
  const now = new Date();
  if (now >= APP_CLOSE_CONFIG.AUTO_CLOSE_TIME) {
    if (!confirm('Perhatian: Waktu pengumuman sudah lewat (batas: 2 Juni 2026 21:00 WIB).\nApakah Anda tetap ingin MEMBUKA kembali akses login siswa?')) return;
  } else {
    if (!confirm('Apakah Anda yakin ingin MEMBUKA KEMBALI akses login siswa?')) return;
  }

  try {
    await setAppClosedStatus(false);
    await refreshSettingsUI();
    showAlert('alert-settings', '<i class="fas fa-check-circle"></i> Akses login siswa berhasil <strong>dibuka kembali untuk semua perangkat/browser</strong>.', 'success');
  } catch (err) {
    console.error(err);
    showAlert('alert-settings', 'Gagal membuka akses di server: ' + err.message, 'error');
  }
}

function logoutAdmin() {
  document.getElementById('admin-user').value = '';
  document.getElementById('admin-pass').value  = '';
  allSiswa = [];
  renderTable([]);
  showPage('page-home');
}

// ============================================================
// DATA
// ============================================================
async function fetchAllData() {
  const res  = await fetch(APPS_SCRIPT_URL + '?action=getAll', { method: 'GET' });
  if (!res.ok) throw new Error('HTTP ' + res.status);
  const json = await res.json();
  return json.data || json || [];
}

async function postData(rows) {
  const res = await fetch(APPS_SCRIPT_URL, {
    method:  'POST',
    headers: { 'Content-Type': 'application/json' },
    body:    JSON.stringify({ action: 'addRows', rows })
  });
  if (!res.ok) throw new Error('HTTP ' + res.status);
  return await res.json();
}

// ============================================================
// DASHBOARD
// ============================================================
async function loadAllData() {
  const icon = document.getElementById('refresh-icon');
  if (icon) icon.style.animation = 'spin 1s linear infinite';
  document.getElementById('table-loading').classList.remove('d-none');
  document.getElementById('table-container').style.opacity = '0.4';
  document.getElementById('table-empty').classList.add('d-none');

  try {
    allSiswa = isDemoMode() ? [...DEMO_DATA] : await fetchAllData();
    updateStats(allSiswa);
    renderTable(allSiswa);
  } catch (e) {
    showAlert('alert-import', 'Gagal memuat data: ' + e.message, 'error');
  } finally {
    document.getElementById('table-loading').classList.add('d-none');
    document.getElementById('table-container').style.opacity = '1';
    if (icon) icon.style.animation = '';
  }
}

function updateStats(data) {
  const total = data.length;
  const lulus = data.filter(d => isStatusLulus(d.Status)).length;
  document.getElementById('stat-total').textContent = total;
  document.getElementById('stat-lulus').textContent = lulus;
  document.getElementById('stat-tidak').textContent = total - lulus;
}

function renderTable(data) {
  const tbody = document.getElementById('tbody-siswa');
  const empty  = document.getElementById('table-empty');
  // Bersihkan peta SKL lama
  Object.keys(_sklMap).forEach(k => delete _sklMap[k]);

  if (!data || data.length === 0) {
    tbody.innerHTML = '';
    empty.classList.remove('d-none');
    return;
  }
  empty.classList.add('d-none');

  tbody.innerHTML = data.map((d, i) => {
    const lulus = isStatusLulus(d.Status);
    // Simpan objek ke map, tombol cukup pakai indeks → aman dari karakter spesial
    _sklMap[i] = d;
    return `<tr>
      <td>${i+1}</td>
      <td><strong>${d.Nama||'-'}</strong></td>
      <td>${d.NIS||'-'}</td>
      <td>${d.NISN||'-'}</td>
      <td>${d.Tempat_Lahir||'-'}</td>
      <td>${formatTanggal(d.Tanggal_Lahir)||'-'}</td>
      <td><span class="${lulus?'badge-lulus':'badge-tidak'}">
        <i class="fas fa-${lulus?'check':'times'}"></i> ${d.Status||'-'}
      </span></td>
      <td>
        <button class="btn-dl-skl" data-idx="${i}">
          <i class="fas fa-file-pdf"></i> SKL
        </button>
      </td>
    </tr>`;
  }).join('');
}

// Event delegation untuk tombol SKL admin — dipasang SEKALI saat DOMContentLoaded
function initAdminTableEvents() {
  const tbody = document.getElementById('tbody-siswa');
  if (!tbody) return;
  tbody.addEventListener('click', (e) => {
    const btn = e.target.closest('button.btn-dl-skl');
    if (!btn) return;
    // Feedback loading pada tombol admin
    const origHtml = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
    const idx   = parseInt(btn.dataset.idx, 10);
    const siswa = _sklMap[idx];
    if (siswa) {
      downloadSKL(siswa).finally(() => {
        btn.disabled = false;
        btn.innerHTML = origHtml;
      });
    } else {
      alert('Data siswa tidak ditemukan.');
      btn.disabled = false;
      btn.innerHTML = origHtml;
    }
  });
}

function filterSiswa() {
  const q = document.getElementById('search-input').value.toLowerCase();
  if (!q) { renderTable(allSiswa); return; }
  const filtered = allSiswa.filter(d =>
    (d.Nama||'').toLowerCase().includes(q) ||
    (d.NISN||'').toLowerCase().includes(q) ||
    (d.NIS||'').toLowerCase().includes(q)
  );
  renderTable(filtered);
  document.getElementById('table-empty').classList.toggle('d-none', filtered.length > 0);
}

// ============================================================
// IMPORT EXCEL
// ============================================================
function importExcel(event) {
  const file = event.target.files[0];
  if (!file) return;
  showAlert('alert-import', '<i class="fas fa-spinner fa-spin"></i> Membaca file Excel...', 'info');

  const reader = new FileReader();
  reader.onload = async (e) => {
    try {
      const wb  = XLSX.read(e.target.result, { type:'binary', cellDates:true });
      const ws  = wb.Sheets[wb.SheetNames[0]];
      const raw = XLSX.utils.sheet_to_json(ws, { defval:'' });

      const rows = raw.map(r => ({
        Nama:          r['Nama']         || r['nama']         || '',
        NIS:           String(r['NIS']   || r['nis']          || ''),
        NISN:          String(r['NISN']  || r['nisn']         || ''),
        Tempat_Lahir:  r['Tempat_Lahir'] || r['Tempat lahir'] || r['tempat_lahir'] || '',
        Tanggal_Lahir: formatTanggalExcel(r['Tanggal_Lahir']  || r['Tanggal lahir'] || r['tanggal_lahir'] || ''),
        Status:        (r['Status'] || r['status'] || 'LULUS').toString().toUpperCase(),
      })).filter(r => r.Nama);

      if (rows.length === 0) {
        showAlert('alert-import', 'Tidak ada data valid. Pastikan kolom: Nama, NIS, NISN, Tempat_Lahir, Tanggal_Lahir, Status', 'error');
        return;
      }

      if (!isDemoMode()) {
        showAlert('alert-import', '<i class="fas fa-spinner fa-spin"></i> Mengirim ke Google Spreadsheet...', 'info');
        await postData(rows);
        await loadAllData();
        showAlert('alert-import', `✅ Berhasil mengimpor ${rows.length} data siswa!`, 'success');
      } else {
        allSiswa = [...allSiswa, ...rows];
        updateStats(allSiswa);
        renderTable(allSiswa);
        showAlert('alert-import', `✅ [DEMO] ${rows.length} data berhasil dimuat.`, 'success');
      }
    } catch (err) {
      showAlert('alert-import', 'Gagal membaca Excel: ' + err.message, 'error');
    }
    event.target.value = '';
  };
  reader.readAsBinaryString(file);
}

// ============================================================
// ASSET GAMBAR – embed langsung dari file Word SK Kelulusan
// (Logo Batang, Logo Tut Wuri, Tanda Tangan, Stempel Resmi)
// ============================================================
const IMG_LOGO_BATANG  = 'data:image/png;base64,';
const IMG_LOGO_TUTWURI = 'data:image/png;base64,';
const IMG_TTD          = 'data:image/png;base64,';
const IMG_STEMPEL      = 'data:image/png;base64,';

// ============================================================
// DOWNLOAD SKL – PDF  (template persis sesuai file Word resmi)
// ============================================================
async function downloadSKL(siswa) {
  if (!siswa) { alert('Data siswa tidak ditemukan.'); return; }

  const btnSiswa     = document.getElementById('btn-download-skl');
  const originalText = btnSiswa ? btnSiswa.innerHTML : null;
  if (btnSiswa) {
    btnSiswa.disabled = true;
    btnSiswa.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Membuat PDF...';
  }

  let JsPDF;
  try {
    JsPDF = await waitForJsPDF(5000);
  } catch (err) {
    alert('Library jsPDF belum siap.\nPastikan koneksi internet aktif dan refresh halaman.\n\nDetail: ' + err.message);
    if (btnSiswa) { btnSiswa.disabled = false; btnSiswa.innerHTML = originalText; }
    return;
  }

  try {
    // ── Setup halaman A4 ─────────────────────────────────────
    const doc   = new JsPDF({ orientation:'portrait', unit:'mm', format:'a4' });
    const pageW = 210;
    const pageH = 297;
    const mL    = 20;     // margin kiri
    const mR    = 17.5;   // margin kanan
    const mT    = 13;     // margin atas (dikompres dari 27 → 13)
    const mB    = 12;     // margin bawah
    const textW = pageW - mL - mR;
    const isLulus = isStatusLulus(siswa.Status);

    // Pastikan semua nilai string
    const sNama        = String(siswa.Nama         || '-');
    const sNIS         = String(siswa.NIS          || '-');
    const sNISN        = String(siswa.NISN         || '-');
    const sTempatLahir = String(siswa.Tempat_Lahir || '-');
    const sTglLahir    = String(formatTanggal(siswa.Tanggal_Lahir) || '-');

    // ════════════════════════════════════════════════════════════
    // KOP SURAT
    // ════════════════════════════════════════════════════════════
    const logoSize  = 24;          // ukuran logo diperkecil
    const logoY     = mT;
    const kopTextY  = mT + 3;      // teks kop mulai sejajar logo

    // Logo kiri (Kabupaten Batang)
    doc.addImage(IMG_LOGO_BATANG, 'PNG', mL, logoY, logoSize, logoSize);

    // Logo kanan (Tut Wuri Handayani)
    doc.addImage(IMG_LOGO_TUTWURI, 'PNG', pageW - mR - logoSize, logoY + 1, logoSize, logoSize);

    // ── Teks kop ────────────────────────────────────────────────
    let y = kopTextY;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11);
    doc.setTextColor(0, 0, 0);
    doc.text('PEMERINTAH KABUPATEN BATANG', pageW / 2, y, { align:'center' });

    y += 6;
    doc.setFontSize(15);
    doc.text('SMP NEGERI 6 BATANG', pageW / 2, y, { align:'center' });

    y += 5;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.text('Jalan Tampangsono Batang   Telepon (0285) 391296   Kode Pos 51214', pageW / 2, y, { align:'center' });

    y += 4.5;
    doc.text('Laman : smpn6batang@yahoo.co.id   ~   Blognet : smpn6batang.wordpress.com', pageW / 2, y, { align:'center' });

    // ── Garis kop ganda ─────────────────────────────────────────
    // Pastikan garis selalu di bawah logo (logoY + logoSize + margin)
    y = Math.max(y + 2, logoY + logoSize + 2);
    doc.setDrawColor(0, 0, 0);
    doc.setLineWidth(0.3);
    doc.line(mL, y, pageW - mR, y);
    y += 1.5;
    doc.setLineWidth(0.8);
    doc.line(mL, y, pageW - mR, y);

    // ════════════════════════════════════════════════════════════
    // JUDUL SK
    // ════════════════════════════════════════════════════════════
    y += 8;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11);
    doc.setTextColor(0, 0, 0);
    doc.text('KEPUTUSAN KEPALA SMP NEGERI 6 BATANG', pageW / 2, y, { align:'center' });

    y += 6;
    doc.text('No. R/105/400.3.11.1/VI/2026', pageW / 2, y, { align:'center' });

    y += 8;
    doc.text('Tentang', pageW / 2, y, { align:'center' });

    y += 8;
    doc.setFontSize(12);
    doc.text('PENETAPAN KELULUSAN PESERTA DIDIK SMP NEGERI 6 BATANG', pageW / 2, y, { align:'center' });

    y += 6;
    doc.text('TAHUN AJARAN 2025/2026', pageW / 2, y, { align:'center' });

    // ════════════════════════════════════════════════════════════
    // DASAR HUKUM
    // ════════════════════════════════════════════════════════════
    y += 8;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);

    const colDasar = mL;
    const colTD    = mL + 17;
    const colNum   = mL + 20;
    const colIsi   = mL + 26;
    const wIsi     = pageW - mR - colIsi;
    const lhDasar  = 5;            // line height dikompres dari 6 → 5

    doc.setFont('helvetica', 'bold');
    doc.text('Dasar', colDasar, y);
    doc.setFont('helvetica', 'normal');
    doc.text(':', colTD, y);

    const dasarIsi = [
      'Peraturan Menteri Pendidikan dan Kebudayaan Nomor 21 Tahun 2022 tentang Standar Penilaian Pendidikan pada Pendidikan Anak Usia Dini, Jenjang Pendidikan Dasar, dan Jenjang Pendidikan Menengah;',
      'Peraturan Menteri Pendidikan, Kebudayaan, Riset dan Teknologi Nomor 58 Tahun 2024 tentang Ijazah Jenjang Pendidikan Dasar dan Pendidikan Menengah;',
      'Peraturan Menteri Pendidikan Dasar dan Menengah Nomor 10 Tahun 2025 tentang Standar Kompetensi Lulusan (SKL) pada Pendidikan Anak Usia Dini (PAUD), Jenjang Pendidikan Dasar, dan Jenjang Pendidikan Menengah;',
      'Permendikdasmen nomor 13 tahun 2025 dan Panduan Pembelajaran Dan Asesmen Edisi Revisi Tahun 2025 tentang penentuan kelulusan;',
      'Hasil Rapat Koordinasi Musyawarah Kerja Kepala Sekolah Kabupaten Batang tanggal 7 Mei 2026;',
      'Peraturan Akademik SMP Negeri 6 Batang Tahun Ajaran 2025/2026;',
      'Hasil Keputusan Rapat Pleno Dewan Guru SMP Negeri 6 Batang tanggal 2 Juni 2026;',
    ];

    // Justify satu baris: distribusi spasi antar kata secara merata
    function justifyLine(text, x, cy, maxW) {
      const words = text.split(' ');
      if (words.length <= 1) { doc.text(text, x, cy); return; }
      const totalW = words.reduce((s, w) => s + doc.getTextWidth(w), 0);
      const gap    = (maxW - totalW) / (words.length - 1);
      let cx = x;
      words.forEach((w, i) => {
        doc.text(w, cx, cy);
        if (i < words.length - 1) cx += doc.getTextWidth(w) + gap;
      });
    }

    y -= lhDasar; // kompensasi agar baris pertama jatuh di y awal
    dasarIsi.forEach((isi, idx) => {
      const nomor = (idx + 1) + '.';
      const lines = doc.splitTextToSize(isi, wIsi);
      lines.forEach((line, li) => {
        y += lhDasar;
        if (li === 0) doc.text(nomor, colNum, y);
        const isLast = (li === lines.length - 1);
        if (isLast) doc.text(line, colIsi, y);
        else        justifyLine(line, colIsi, y, wIsi);
      });
    });

    // ════════════════════════════════════════════════════════════
    // MEMUTUSKAN
    // ════════════════════════════════════════════════════════════
    y += 10;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    doc.text('Memutuskan', pageW / 2, y, { align:'center' });

    y += 8;
    doc.text('Menetapkan  :  Bahwa peserta didik di bawah ini :', mL, y);

    // ════════════════════════════════════════════════════════════
    // DATA PESERTA DIDIK
    // ════════════════════════════════════════════════════════════
    y += 8;
    const colonX = mL + 55;
    const valX   = colonX + 4;
    const rowH   = 6.5;

    const fields = [
      { label: 'Nama',                     val: sNama },
      { label: 'Tempat dan Tanggal Lahir', val: sTempatLahir + ', ' + sTglLahir },
      { label: 'NIS',                      val: sNIS },
      { label: 'NISN',                     val: sNISN },
    ];

    doc.setFontSize(11);
    fields.forEach(f => {
      doc.setFont('helvetica', 'normal');
      doc.text(f.label, mL, y);
      doc.text(':', colonX, y);
      doc.setFont('helvetica', 'normal');
      doc.text(String(f.val), valX, y);
      y += rowH;
    });

    // ════════════════════════════════════════════════════════════
    // PERNYATAAN STATUS
    // ════════════════════════════════════════════════════════════
    y += 3;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    doc.setTextColor(0, 0, 0);
    doc.text('Sesuai dengan keputusan dewan guru, siswa dengan identitas tersebut dinyatakan :', mL, y);

    y += 8;
    const statusText  = isLulus ? 'L U L U S' : 'TIDAK  LULUS';
    const statusColor = [0, 0, 0];
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(18);
    doc.setTextColor(...statusColor);
    doc.text(statusText, pageW / 2, y, { align:'center' });

    y += 6;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    doc.setTextColor(0, 0, 0);
    doc.text('dari Satuan Pendidikan SMP Negeri 6 Batang Tahun Ajaran 2025/2026.', mL, y);

    y += 6;
    doc.text('Demikian surat keputusan ini dibuat agar dapat digunakan sebagaimana mestinya.', mL, y);

    // ════════════════════════════════════════════════════════════
    // TANDA TANGAN & STEMPEL
    // ════════════════════════════════════════════════════════════
    y += 10;
    const yTTDsection = y;

    // Kolom TTD di kanan — semua teks rata kiri dari ttdX agar satu garis lurus
    const ttdX  = mL + 95;  // titik kiri blok TTD
    const ttdCx = ttdX + 25; // pusat blok TTD (untuk gambar TTD & stempel)

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    doc.setTextColor(0, 0, 0);
    doc.text('Batang, 2 Juni 2026', ttdX, y);
    y += 5.5;
    const yKepalaSekolah = y;
    doc.text('Kepala Sekolah,', ttdX, y);

    // ── TTD: di bawah teks "Kepala Sekolah," ───────────────────
    const ttdW  = 34, ttdH = 34;
    const ttdAbsX = ttdCx - ttdW / 2;
    const ttdAbsY = yKepalaSekolah + 2;
    doc.addImage(IMG_TTD, 'PNG', ttdAbsX, ttdAbsY, ttdW, ttdH);

    // ── Stempel: overlap separuh kiri TTD ──────────────────────
    const stpW  = 35, stpH = 35;
    const stempelAbsX = ttdCx - stpW;
    const stempelAbsY = ttdAbsY - 1;
    doc.addImage(IMG_STEMPEL, 'PNG', stempelAbsX, stempelAbsY, stpW, stpH);

    // Nama & NIP kepala sekolah — rata kiri dari ttdX
    y = ttdAbsY + ttdH + 4;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11);
    doc.setTextColor(0, 0, 0);
    doc.text('Ari Tonang, S.Pd., M.Si.', ttdX, y);

    y += 5.5;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(11);
    doc.text('NIP. 197210201999031010', ttdX, y);

    // ── Validasi: pastikan konten tidak melampaui batas bawah ──
    if (y > pageH - mB) {
      console.warn('[downloadSKL] Konten melebihi batas halaman. y=' + y.toFixed(1) + 'mm, batas=' + (pageH - mB) + 'mm');
    }

    // ── SIMPAN PDF ─────────────────────────────────────────────
    const safeName = sNama.replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_]/g, '');
    doc.save('SKL_' + safeName + '_' + sNISN + '.pdf');

  } catch (err) {
    console.error('[downloadSKL] Error:', err);
    alert('Gagal membuat PDF.\n\nDetail error: ' + err.message + '\n\nSilakan refresh halaman dan coba lagi.');
  } finally {
    if (btnSiswa) {
      btnSiswa.disabled = false;
      btnSiswa.innerHTML = originalText;
    }
  }
}
// ============================================================
// UTILITAS
// ============================================================
function isStatusLulus(status) {
  const s = (status || '').toUpperCase();
  return s.includes('LULUS') && !s.includes('TIDAK');
}

const BULAN_ID = [
  'Januari','Februari','Maret','April','Mei','Juni',
  'Juli','Agustus','September','Oktober','November','Desember'
];

function formatTanggal(raw) {
  if (!raw) return '';
  try {
    if (typeof raw === 'number') {
      const d = new Date(Math.round((raw - 25569) * 86400 * 1000));
      return `${d.getUTCDate()} ${BULAN_ID[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
    }
    const d = new Date(raw);
    if (isNaN(d)) return raw;
    return `${d.getDate()} ${BULAN_ID[d.getMonth()]} ${d.getFullYear()}`;
  } catch { return raw; }
}

function formatTanggalExcel(raw) {
  if (!raw) return '';
  if (raw instanceof Date) return raw.toISOString().split('T')[0];
  return String(raw);
}

// ============================================================
// HIDDEN ADMIN – Gembok kecil + kode rahasia
// ============================================================
const SECRET_CODE        = 'admin2026';   // ← ganti sesuai keinginan
const SECRET_STORAGE_KEY = 'smpn6_admin_visible';

function isAdminVisible() {
  return sessionStorage.getItem(SECRET_STORAGE_KEY) === '1';
}

function showAdminBtn() {
  sessionStorage.setItem(SECRET_STORAGE_KEY, '1');
  const btn  = document.getElementById('btn-admin-secret');
  const lock = document.getElementById('btn-lock-trigger');
  const icon = document.getElementById('lock-icon');
  if (btn)  btn.classList.add('visible');
  if (lock) lock.classList.add('unlocked');
  if (icon) { icon.classList.remove('fa-lock'); icon.classList.add('fa-lock-open'); }
}

function hideAdminBtn() {
  sessionStorage.removeItem(SECRET_STORAGE_KEY);
  const btn  = document.getElementById('btn-admin-secret');
  const lock = document.getElementById('btn-lock-trigger');
  const icon = document.getElementById('lock-icon');
  if (btn)  btn.classList.remove('visible');
  if (lock) lock.classList.remove('unlocked');
  if (icon) { icon.classList.remove('fa-lock-open'); icon.classList.add('fa-lock'); }
}

function handleLockClick() {
  const lockBtn = document.getElementById('btn-lock-trigger');
  // Animasi pop
  if (lockBtn) {
    lockBtn.classList.remove('pop');
    void lockBtn.offsetWidth;
    lockBtn.classList.add('pop');
    lockBtn.addEventListener('animationend', () => lockBtn.classList.remove('pop'), { once: true });
  }
  if (isAdminVisible()) {
    hideAdminBtn();
  } else {
    openSecretModal();
  }
}

function openSecretModal() {
  const modal = document.getElementById('modal-secret');
  if (!modal) return;
  document.getElementById('secret-code-input').value = '';
  document.getElementById('alert-secret').classList.add('d-none');
  modal.style.display = 'flex';
  setTimeout(() => document.getElementById('secret-code-input').focus(), 100);
}

function closeSecretModal() {
  const modal = document.getElementById('modal-secret');
  if (modal) modal.style.display = 'none';
}

function verifySecretCode() {
  const input = document.getElementById('secret-code-input').value.trim();
  const alertEl = document.getElementById('alert-secret');
  if (!input) {
    alertEl.className = 'alert-custom error';
    alertEl.innerHTML = '<i class="fas fa-exclamation-circle"></i> Kode rahasia tidak boleh kosong.';
    alertEl.classList.remove('d-none');
    return;
  }
  if (input === SECRET_CODE) {
    closeSecretModal();
    showAdminBtn();
  } else {
    alertEl.className = 'alert-custom error';
    alertEl.innerHTML = '<i class="fas fa-times-circle"></i> Kode salah. Silakan coba lagi.';
    alertEl.classList.remove('d-none');
    document.getElementById('secret-code-input').value = '';
    document.getElementById('secret-code-input').focus();
  }
}

