document.addEventListener('DOMContentLoaded', () => {
  showPage('page-home');
  initParticles();
  initAdminTableEvents(); // event delegation SKL tombol admin
  // Pulihkan visibilitas tombol admin jika session masih aktif
  if (isAdminVisible()) showAdminBtn();

  // Enter / Escape key untuk modal kode rahasia
  document.getElementById('secret-code-input')?.addEventListener('keydown', e => {
    if (e.key === 'Enter') verifySecretCode();
    if (e.key === 'Escape') closeSecretModal();
  });

  document.getElementById('siswa-nisn')?.addEventListener('keydown', e => { if (e.key==='Enter') loginSiswa(); });
  document.getElementById('admin-user')?.addEventListener('keydown', e => { if (e.key==='Enter') loginAdmin(); });
  document.getElementById('admin-pass')?.addEventListener('keydown', e => { if (e.key==='Enter') loginAdmin(); });
});
